package com.mewcode.tool;
import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.StandardCopyOption;
public final class AtomicFileWriter {private AtomicFileWriter(){} public static void write(Path target,String content)throws java.io.IOException{Path absolute=target.toAbsolutePath().normalize();if(absolute.getParent()!=null)Files.createDirectories(absolute.getParent());Path temp=Files.createTempFile(absolute.getParent(),".minicode-",".tmp");try{Files.writeString(temp,content,StandardCharsets.UTF_8);try{Files.move(temp,absolute,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(java.nio.file.AtomicMoveNotSupportedException e){Files.move(temp,absolute,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}}
